head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > setRowDisabled]<br/>Row 인덱스를 사용하여 특정 Row 의 disabled 상태를 설정합니다.",
    "validation" : [
        "GridView 가 비활성화(disabled) 상태인 경우 Row/Column/Cell 의 비활성화(disabled) 상태가 해제되지 않아야 합니다. (편집 불가를 의미)",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createLabel('label="초기 상태는 모든 셀 enabled. GridView disabled 토글로 GridView 를 disabled 로 설정한 뒤 setRowDisabled(row, false) 로 해제를 시도하면, 현재 엔진은 배경색을 흰색(enabled 처럼 표시)으로 바꾸지만 편집은 불가능한 상태가 유지됨을 확인"', '', 'label1');

    // 조건 설정 (disabled Cell 을 배경색으로 구분: disabled=회색)
    let properties = {
        dataList: "data:dlt_bind",
        disabledBackgroundColor: "#D3D3D3",
        readOnlyBackgroundColor: "#FFF8DC",
    };

    let cList = $c.gcm.createCList(properties);

    // dataList 생성 (기본 4행)
    $c.gcm.createBasicDataList('', '', 'dlt_bind');

    // target 생성 (초기 상태는 모든 셀 enabled)
    await $c.gcm.createBasicGridView(cList);
}



scwin.btn_setRowDisabled_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());
    let disabledText = par_disabled.getValue();

    if (disabledText === 'omit') {
        // 파라미터 생략 (기본값 false)
        target1.setRowDisabled(rowIndex);
        wf_body_bottom.getObj("scwin").setReturnValue("setRowDisabled(" + rowIndex + ")");
    } else if (disabledText === '') {
        // 빈 문자열 설정 (GridView 의 disabled 상태 적용)
        target1.setRowDisabled(rowIndex, "");
        wf_body_bottom.getObj("scwin").setReturnValue("setRowDisabled(" + rowIndex + ", '')");
    } else {
        let disabled = disabledText === 'true';
        target1.setRowDisabled(rowIndex, disabled);
        wf_body_bottom.getObj("scwin").setReturnValue("setRowDisabled(" + rowIndex + ", " + disabled + ")");
    }

    scwin.btn_getRowDisabled_onclick();
}



scwin.btn_getRowDisabled_onclick = function () {
    let rowIndex = Number(par_rowIndex.getValue());

    // Row 단위 disabled 상태 (getRowDisabled)
    let rowRtn = target1.getRowDisabled(rowIndex);
    // 최종 적용된 실제 disabled 상태 (getDisabled('all') : GridView/Row/Column/Cell 우선순위 반영)
    let allRtn = target1.getDisabled("all", rowIndex, 0);

    wf_body_bottom.getObj("scwin").setReturnValue("getRowDisabled(" + rowIndex + ") [Row 단위] : " + rowRtn);
    wf_body_bottom.getObj("scwin").setReturnValue("getDisabled('all', " + rowIndex + ", 0) [최종 적용] : " + allRtn);
}



// GridView 전체(grid) 단위 disabled 토글 (GridView disabled 시 하위 Row/Column/Cell disabled 가 해제되지 않음을 검증)
scwin.gVar = { "gridDisabled": false };
scwin.btn_toggleGridDisabled_onclick = function () {
    scwin.gVar.gridDisabled = !scwin.gVar.gridDisabled;
    target1.setDisabled("grid", scwin.gVar.gridDisabled);
    wf_body_bottom.getObj("scwin").setReturnValue("setDisabled('grid', " + scwin.gVar.gridDisabled + ") 실행");
}
